<div class="rounded-xl border border-slate-200 bg-white p-6 shadow-sm"><h2 class="text-xl font-bold"><?=e($report['report_type'])?> Report</h2><dl class="mt-6 grid gap-5 sm:grid-cols-2 lg:grid-cols-3"><?php foreach(['Reporting period'=>$report['reporting_period_start'].' – '.$report['reporting_period_end'],'Submitted date'=>$report['submitted_date'],'Submitted by'=>$report['submitter_name'],'Reviewed by'=>$report['reviewer_name']?:'Not reviewed','Approval status'=>$report['approval_status'],'Version'=>$report['report_version'],'Generated by system'=>!empty($report['generated_by_system'])?'Yes':'No','Remarks'=>$report['remarks']?:'Not recorded'] as $l=>$v):?><div><dt class="text-sm text-slate-500"><?=e($l)?></dt><dd class="mt-1 font-medium"><?=e((string)$v)?></dd></div><?php endforeach;?></dl></div>
